  # XSEC SCALING
  anv1res = 0.06554999947547913
  anv2res = 0.35017499327659607
  anv3res = 0.7417500019073486
  amphar = 0.862500011920929
  a0 = 5.291772083e-9
  ry = 13.605691909790039
  # BORN-BETHE VALUES FOR IONISATION
  `const` = 1.873884e-20
  emass2 = 1021997.8125
  api = arccos((-1.0))
  bbconst = 16.0 * api * a0 * a0 * ry * ry / emass2
  # CONSTANTS FOR IONISATION
  am2 = 20.5
  c = 235.0
  nasize = 4000
  nbrem = 25
  nrtang = 145
  nion = 9
  natt = 2
  nin = 24
  nnull = 0
  fdo j, 1, nin:
    izbr[j] = 0
  izbr[nin + 1] = 6
  izbr[nin + 2] = 9
  # USE OKHRIMOVSKKY FOR ELASTIC AND IONISATION
  fdo j, 1, 6:
    kel[j] = 2
