  efl[9] = 668.0
  ng1[9] = 2
  eg1[9] = 625.2000122070312
  ng2[9] = 1
  eg2[9] = 5.0
  ein[1] = (-0.06499999761581421)
  ein[2] = (-0.06499999761581421)
  ein[3] = (-0.10000000149011612)
  ein[4] = (-0.10000000149011612)
  ein[5] = (-0.1550000011920929)
  ein[6] = (-0.1550000011920929)
  ein[7] = 0.06499999761581421
  ein[8] = 0.06499999761581421
  ein[9] = 0.10000000149011612
  ein[10] = 0.10000000149011612
  ein[11] = 0.1550000011920929
  ein[12] = 0.1550000011920929
  ein[13] = 0.3499999940395355
  ein[14] = 0.5
  ein[15] = 9.399999618530273
  ein[16] = 9.5
  ein[17] = 10.399999618530273
  ein[18] = 10.5
  ein[19] = 11.800000190734863
  ein[20] = 11.899999618530273
  ein[21] = 13.5
  ein[22] = 14.800000190734863
  ein[23] = 15.5
  ein[24] = 20.5
  # OFFSET ENERGY FOR IONISATION ELECTRON ANGULAR DISTRIBUTION
  fdo j, 1, nion:
    block L40:
      fdo i, 1, nasize:
        if mix2.eg[i] > eion[j]:
          ioffion[j] = i - 1
          break L40
  # OFFSET ENERGY FOR EXCITATION ANGULAR DISTRIBUTION
  fdo nl, 1, nin:
    block L50:
      fdo i, 1, nasize:
        if mix2.eg[i] > abs(ein[nl]):
          ioffn[nl] = i - 1
          break L50
  # ENTER PENNING TRANSFER FRACTION FOR EACH LEVEL
  # SET PENNING TRANSFER FRACTION TO ZERO FOR LOW LEVELS
  fdo k, 1, nin:
    fdo l, 1, 3:
      penfra[l, k] = 0.0
  # PENNING TRANSFER FRACTION FOR LEVELS ABOVE 6.0EV
  fdo k, 61, nin:
    penfra[1, k] = 0.0
    # PENNING TRANSFER DISTANCE IN MICRONS
    penfra[2, k] = 1.0
    # PENNING TRANSFER TIME IN PICOSECONDS
    penfra[3, k] = 1.0
    if not (inpt.ipen == 0):
      fwrite(fmt999, name, ein[k], penfra[1, k], penfra[2, k], penfra[3, k])
  scrpt[1] = fstr("                                                  ", 50)
  if inpt.naniso == 2:
    scrpt[2] = fstr(" ELASTIC   ANISOTROPIC C3F8  CARBON HEXAFLUORIDE  ", 50)
  elif inpt.naniso == 0:
    scrpt[2] = fstr(" ELASTIC     ISOTROPIC C3F8  CARBON HEXAFLUORIDE  ", 50)
  else:
    fwrite(fmt998)
    fstop()
  scrpt[3] = fstr(" IONISATION DISSOCIATIVE   CF3 +   ELOSS=  13.35  ", 50)
  scrpt[4] = fstr(" IONISATION DISSOCIATIVE  C2F5 +   ELOSS=  13.35  ", 50)
  scrpt[5] = fstr(" IONISATION DISSOCIATIVE  C2F4 +   ELOSS=  13.50  ", 50)
  scrpt[6] = fstr(" IONISATION DISSOCIATIVE  C3F7 +   ELOSS=  15.45  ", 50)
  scrpt[7] = fstr(" IONISATION DISSOCIATIVE    CF +   ELOSS=  21.1   ", 50)
  scrpt[8] = fstr(" IONISATION DISSOCIATIVE   CF2 +   ELOSS=  26.7   ", 50)
