  scrpt[10] = fstr(" IONISATION    CARBON   K-SHELL    ELOSS= 285.0   ", 50)
  scrpt[11] = fstr(" IONISATION    FLUORINE K-SHELL    ELOSS= 685.4   ", 50)
  scrpt[12] = fstr(" ATTACHMENT  2 BODY DISSOCATIVE (F-)              ", 50)
  scrpt[13] = fstr(" ATTACHMENT  3 BODY (C3F8-)                       ", 50)
  scrpt[14] = fstr("                                                  ", 50)
  scrpt[15] = fstr("                                                  ", 50)
  scrpt[16] = fstr(" VIB V1 DIPOLE ONLY                ELOSS= -0.065  ", 50)
  scrpt[17] = fstr(" VIB1   RESONANCE ONLY             ELOSS= -0.065  ", 50)
  scrpt[18] = fstr(" VIB V2  DIPOLE ONLY               ELOSS= -0.100  ", 50)
  scrpt[19] = fstr(" VIB V2  RESONANCE ONLY            ELOSS= -0.100  ", 50)
  scrpt[20] = fstr(" VIB V3  DIPOLE ONLY               ELOSS= -0.155  ", 50)
  scrpt[21] = fstr(" VIB V3  RESONANCE ONLY            ELOSS= -0.155  ", 50)
  scrpt[22] = fstr(" VIB V1  DIPOLE ONLY               ELOSS=  0.065  ", 50)
  scrpt[23] = fstr(" VIB V1  RESONANCE ONLY            ELOSS=  0.065  ", 50)
  scrpt[24] = fstr(" VIB V2  DIPOLE ONLY               ELOSS=  0.100  ", 50)
  scrpt[25] = fstr(" VIB V2  RESONANCE ONLY            ELOSS=  0.100  ", 50)
  scrpt[26] = fstr(" VIB V3  DIPOLE ONLY               ELOSS=  0.155  ", 50)
  scrpt[27] = fstr(" VIB V3  RESONANCE ONLY            ELOSS=  0.155  ", 50)
  scrpt[28] = fstr(" VIB 2V3                           ELOSS=  0.35   ", 50)
  scrpt[29] = fstr(" VIB                               ELOSS=  0.50   ", 50)
  scrpt[30] = fstr(" NEUTRAL DISS   NON-DIPOLE         ELOSS=  9.4    ", 50)
  scrpt[31] = fstr(" NEUTRAL DISS   DIPOLE    F=0.032  ELOSS=  9.5    ", 50)
  scrpt[32] = fstr(" NEUTRAL DISS   NON-DIPOLE         ELOSS= 10.4    ", 50)
  scrpt[33] = fstr(" NEUTRAL DISS   DIPOLE    F=0.054  ELOSS= 10.5    ", 50)
  scrpt[34] = fstr(" NEUTRAL DISS   NON-DIPOLE         ELOSS= 11.8    ", 50)
  scrpt[35] = fstr(" NEUTRAL DISS   DIPOLE    F=0.252  ELOSS= 11.9    ", 50)
  scrpt[36] = fstr(" NEUTRAL DISS   DIPOLE    F=0.941  ELOSS= 13.5    ", 50)
  scrpt[37] = fstr(" NEUTRAL DISS   NON-DIPOLE         ELOSS= 14.8    ", 50)
  scrpt[38] = fstr(" NEUTRAL DISS   DIPOLE    F=10.4   ELOSS= 15.5    ", 50)
  scrpt[39] = fstr(" NEUTRAL DISS   DIPOLE    F=5.20   ELOSS= 20.5    ", 50)
  # DENSITY CORERCTION FOR 3-BODY ATTACHMENT CROSS-SECTION
  # CRITICAL DENSITY : 31 TORR = ANCRIT
  ancrit = 31.0
  fac = 1.0 / (ancrit / inpt.torr + 1.0)
  # write(6,99) FAC,TORR,ANCRIT
  # 99  format(' FAC=',D12.4,' TORR=',D12.4' ncrit=',D12.4)
  # GROUPED VIBRATIONS SO NO DEGENERACY CALCULATION POSSIBLE
  # USED INDEPENDENT APPROXIMATION FOR UPPER STATE POPULATION
  apop1 = exp(ein[1] / inpt.akt)
  apop2 = exp(ein[3] / inpt.akt)
  apop3 = exp(ein[5] / inpt.akt)
  # RENORMALISE GS POPULATION TO ACCOUNT FOR EXCITATION FROM EXCITED STATE
  apopgs = 1.0
  fdo i, 1, inpt.nstep:
    en = mix2.eg[i]
    gamma1 = (emass2 + 2.0 * en) / emass2
    gamma2 = gamma1 * gamma1
    beta = sqrt(1.0 - 1.0 / gamma2)
    beta2 = beta * beta
    # ELASTIC CALCULATION
    q[2, i] = 0.0
    block L20:
      if en <= xel[1]:
        qela = yel[1] * 1e-16
        qmmt = ymt[1] * 1e-16
        eps = yeps[1]
        break L20
      block L19:
        fdo j, 2, ndata:
          if en <= xel[j]: break L19
        j = ndata
      # USE LOG INTERPOLATION
      yxj = ln(yel[j])
      yxj1 = ln(yel[j - 1])
      xnj = ln(xel[j])
      xnj1 = ln(xel[j - 1])
      a = (yxj - yxj1) / (xnj - xnj1)
      b = (xnj1 * yxj - xnj * yxj1) / (xnj1 - xnj)
      qela = exp(a * ln(en) + b) * 1e-16
      yxj = ln(ymt[j])
      yxj1 = ln(ymt[j - 1])
      a = (yxj - yxj1) / (xnj - xnj1)
      b = (xnj1 * yxj - xnj * yxj1) / (xnj1 - xnj)
      qmmt = exp(a * ln(en) + b) * 1e-16
      # ANGULAR DISTRIBUTION FOR ELASTICS (OKHRIMOVSSKY)
      a = (yeps[j] - yeps[j - 1]) / (xel[j] - xel[j - 1])
      b = (xel[j - 1] * yeps[j] - xel[j] * yeps[j - 1]) / (xel[j - 1] - xel[j])
      eps = a * en + b
    # CONVERT TO (1.0-EPS)
    eps = 1.0 - eps
    if inpt.naniso == 2:
      # USE ELASTIC (ANISOTROPIC SCATTERING)
      q[2, i] = qela
      peqel[2, i] = eps
    elif inpt.naniso == 0:
      # USE ISOTROPIC MT ELASTIC
      q[2, i] = qmmt
      peqel[2, i] = 0.0
    else:
