      fstop()
    # ZERO IONISATION ARRAYS
    fdo j, 1, nion:
      peqion[j, i] = 0.0
      qion[j, i] = 0.0
    block L190:
      # IF ENERGY GT 3 KEV USE OSCILLATOR STRENGTH FOR IONISATION
      # CALCULATE  COUNTING AND GROSS IONISATION
      if en < eion[1]: break L190
      block L145:
        block L140:
          if en > 3000.0: break L140
          block L103:
            fdo j, 2, nionc:
              if en <= xion[j]: break L103
            j = nionc
          x1 = ln(xion[j])
          x2 = ln(xion[j - 1])
          y1 = ln(yionc[j])
          y2 = ln(yionc[j - 1])
          a = (y1 - y2) / (x1 - x2)
          b = (x2 * y1 - x1 * y2) / (x2 - x1)
          qionc = exp(a * ln(en) + b) * 1e-16
          y1 = ln(yiong[j])
          y2 = ln(yiong[j - 1])
          a = (y1 - y2) / (x1 - x2)
          b = (x2 * y1 - x1 * y2) / (x2 - x1)
          qiong = exp(a * ln(en) + b) * 1e-16
          block L109:
            block L108:
              # IONISATION TO CF3 +
              if en > 200.0: break L108
              block L107:
                fdo j, 2, nion1:
                  if en <= xion1[j]: break L107
                j = nion1
              x1 = ln(xion1[j])
              x2 = ln(xion1[j - 1])
              y1 = ln(yion1[j])
              y2 = ln(yion1[j - 1])
              a = (y1 - y2) / (x1 - x2)
              b = (x2 * y1 - x1 * y2) / (x2 - x1)
